import { useLocalization } from "@jcoder-stack/abp-react/react";
import { createFormHook, createFormHookContexts } from "@tanstack/react-form";
import type { ReactNode } from "react";
import { createContext, lazy, Suspense, useContext } from "react";
import { Combobox } from "@/components/combobox/combobox";
import type { ComboboxOption } from "@/components/combobox/use-combobox-options";
import { formatIso, ISO_DATE, ISO_DATE_TIME, parseIso } from "@/components/date-picker/date-io";
import { TimeInput } from "@/components/date-picker/time-input";
import { FormErrorSummary } from "@/components/form/form-error-summary";
import { OptionalMark } from "@/components/form/optional-mark";
import { Badge } from "@/components/ui/badge";
import {
  Field,
  FieldContent,
  FieldDescription,
  FieldError,
  FieldLabel,
} from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

const MultiCombobox = lazy(() =>
  import("@/components/combobox/multi-combobox").then((m) => ({ default: m.MultiCombobox })),
);
const DatePicker = lazy(() =>
  import("@/components/date-picker/date-picker").then((m) => ({ default: m.DatePicker })),
);
const DateTimePicker = lazy(() =>
  import("@/components/date-picker/date-time-picker").then((m) => ({
    default: m.DateTimePicker,
  })),
);
const DateRangePicker = lazy(() =>
  import("@/components/date-picker/date-range-picker").then((m) => ({
    default: m.DateRangePicker,
  })),
);

export const { fieldContext, formContext, useFieldContext, useFormContext } =
  createFormHookContexts();

/** 错误元素可能是服务端原始字符串或 Standard Schema issue;FieldError 只认 {message}。 */
function toFieldErrors(errors: unknown[]): { message?: string }[] {
  return errors.map((e) => (typeof e === "string" ? { message: e } : (e as { message?: string })));
}

interface ServerErrorFieldMeta {
  errorMap?: Record<string, unknown>;
}

/** `clearServerSubmitErrors` 需要的最小结构面,避免依赖 TanStack Form 的完整泛型形态。 */
interface ServerErrorForm {
  state: { fieldMeta: Record<string, ServerErrorFieldMeta | undefined> };
  setFieldMeta: (
    name: string,
    updater: (meta: ServerErrorFieldMeta) => ServerErrorFieldMeta,
  ) => void;
  setErrorMap: (map: { onSubmit?: undefined }) => void;
}

/**
 * 绕过 @tanstack/react-form 1.33.2 死锁:onSubmitAsync 注入的字段级错误不会在重提交时自清,
 * 不清则提交被永久短路。约束:onSubmit 槽位只放服务端错误,勿给 field 另挂 onSubmit 校验器。
 */
function clearServerSubmitErrors(form: ServerErrorForm): void {
  for (const name of Object.keys(form.state.fieldMeta)) {
    form.setFieldMeta(name, (meta) => ({
      ...meta,
      errorMap: { ...meta.errorMap, onSubmit: undefined },
    }));
  }
  form.setErrorMap({ onSubmit: undefined });
}

/**
 * 「选填」标记开关。
 *
 * 标少数派才有意义，而少数派是谁取决于**整张表单的构成**，不是单个字段：录入表单里多数字段
 * 必填，标出那一两个选填的很有用；查询表单里字段本来就全是选填，逐个标等于每个标签都挂一句
 * 废话。所以这个决定放在表单层——SheetForm 打开它，查询表单不打开。
 */
const OptionalMarksContext = createContext(false);

/**
 * 只读渲染开关。打开后字段不再渲染「禁用的控件」，而是渲染一行「键 / 值」。
 *
 * 禁用控件的对比度是 WCAG 明确豁免的——豁免的前提正是它**不承载内容**。用一排灰掉的输入框
 * 展示一条记录，既难读又像坏了，用户还会去点那些框。
 *
 * 渲染归字段管（只有它知道该把枚举值、日期、布尔显示成什么），容器归表单管，调用方的写法
 * 一个字都不用改。
 */
const ReadOnlyContext = createContext(false);

export function ReadOnlyFields(props: { children: ReactNode }) {
  return <ReadOnlyContext.Provider value={true}>{props.children}</ReadOnlyContext.Provider>;
}

/** 当前是否处在查看态。字段组件自己会查，导出是给排版层用——查看态的容器只认识 `FieldRow`，
 *  页面为录入态写的栅格与提示必须自行退场，否则会把键值卡的对齐和分隔线打散。 */
export function useReadOnly(): boolean {
  return useContext(ReadOnlyContext);
}

/**
 * 只读态的一行：左键右值，行高与表格同源（40px），值右对齐排成一条竖线。
 *
 * 导出给页面自己排「不是表单字段」的那一行（计算值、关联记录的摘要），让它与生成字段落在同一
 * 条竖线上。`display` 为 `null`/空串/NaN 时渲染成「未填写」；只在 `ReadOnlyFields` 的 `<dl>`
 * 里使用，它输出的是 `<dt>/<dd>`。
 */
export function FieldRow(props: { label: string; display: ReactNode }) {
  const L = useLocalization();
  const empty =
    props.display === undefined ||
    props.display === null ||
    props.display === "" ||
    (typeof props.display === "number" && Number.isNaN(props.display));
  return (
    <div className="flex min-h-10 items-center justify-between gap-4 px-3 py-2">
      <dt className="shrink-0 text-sm text-muted-foreground">{props.label}</dt>
      <dd className={cn("text-right text-sm", empty && "text-muted-foreground")}>
        {empty ? L("Form:Empty") : props.display}
      </dd>
    </div>
  );
}

export function OptionalMarks(props: { children: ReactNode }) {
  return (
    <OptionalMarksContext.Provider value={true}>{props.children}</OptionalMarksContext.Provider>
  );
}

/**
 * 字段外壳：标签 → 说明 → 控件 → 错误，顺序恒定。
 *
 * 说明刻意放在控件**之上**：控件下方是错误信息的位置，两者挤在一起时，出错那一刻要么说明
 * 被顶走、要么错误被推到看不见的地方。
 */
function FieldShell(props: {
  label: string;
  required?: boolean;
  description?: string;
  /**
   * 只读态下这个字段该显示成什么。
   *
   * `null` 表示「接了只读渲染，但此刻没有值」——渲染成「未填写」那一行。
   * `undefined` 表示「这个字段还没接只读渲染」，回退到禁用控件。两者不能混用：空值若传
   * undefined，就会在只读的键值卡里冒出一个控件，把整张卡的排版撑坏。
   */
  display?: ReactNode;
  orientation?: "vertical" | "horizontal";
  children: ReactNode;
}) {
  const field = useFieldContext();
  const invalid = field.state.meta.errors.length > 0;
  const marksOptional = useContext(OptionalMarksContext);
  const readOnly = useContext(ReadOnlyContext);
  if (readOnly && props.display !== undefined) {
    return <FieldRow label={props.label} display={props.display} />;
  }
  const label = (
    <FieldLabel htmlFor={field.name}>
      {props.label}
      {marksOptional && props.required !== true && <OptionalMark />}
    </FieldLabel>
  );
  const description = props.description !== undefined && (
    <FieldDescription>{props.description}</FieldDescription>
  );
  const error = <FieldError errors={toFieldErrors(field.state.meta.errors)} />;
  if (props.orientation === "horizontal") {
    // 横排时说明与错误都归到标签那一列，控件留在行尾——否则它们会挤进同一行把开关推走。
    return (
      <Field orientation="horizontal" data-invalid={invalid ? true : undefined}>
        <FieldContent>
          {label}
          {description}
          {error}
        </FieldContent>
        {props.children}
      </Field>
    );
  }
  return (
    <Field orientation={props.orientation} data-invalid={invalid ? true : undefined}>
      {label}
      {description}
      {props.children}
      {error}
    </Field>
  );
}

export function TextField(props: {
  label: string;
  required?: boolean;
  description?: string;
  type?: "text" | "email" | "password" | "date";
  disabled?: boolean;
  placeholder?: string;
  autoComplete?: string;
}) {
  const field = useFieldContext<string>();
  return (
    <FieldShell
      label={props.label}
      required={props.required}
      description={props.description}
      display={field.state.value}
    >
      <Input
        id={field.name}
        name={field.name}
        type={props.type ?? "text"}
        aria-required={props.required === true || undefined}
        aria-invalid={field.state.meta.errors.length > 0 || undefined}
        value={field.state.value}
        disabled={props.disabled}
        placeholder={props.placeholder}
        autoComplete={props.autoComplete}
        onBlur={field.handleBlur}
        onChange={(event) => field.handleChange(event.target.value)}
      />
    </FieldShell>
  );
}

/** 多行文本字段，值域是整块字符串；按行拆分的语义由调用方的 toDto / fromDto 决定。 */
export function TextareaField(props: {
  label: string;
  required?: boolean;
  description?: string;
  disabled?: boolean;
  placeholder?: string;
  rows?: number;
}) {
  const field = useFieldContext<string>();
  return (
    <FieldShell
      label={props.label}
      required={props.required}
      description={props.description}
      display={
        field.state.value ? <span className="whitespace-pre-wrap">{field.state.value}</span> : null
      }
    >
      <Textarea
        id={field.name}
        name={field.name}
        rows={props.rows}
        aria-required={props.required === true || undefined}
        aria-invalid={field.state.meta.errors.length > 0 || undefined}
        value={field.state.value}
        disabled={props.disabled}
        placeholder={props.placeholder}
        onBlur={field.handleBlur}
        onChange={(event) => field.handleChange(event.target.value)}
      />
    </FieldShell>
  );
}

/**
 * 时刻字段，值域 `"HH:mm"`（空串表示未填），24 小时制。对应后端 TimeSpan 时，调用方在
 * toDto / fromDto 里补齐或截掉秒段。
 */
export function TimeField(props: {
  label: string;
  required?: boolean;
  description?: string;
  disabled?: boolean;
}) {
  const field = useFieldContext<string>();
  return (
    <FieldShell
      label={props.label}
      required={props.required}
      description={props.description}
      display={field.state.value ? <span className="tabular-nums">{field.state.value}</span> : null}
    >
      <TimeInput
        id={field.name}
        name={field.name}
        aria-required={props.required === true || undefined}
        aria-invalid={field.state.meta.errors.length > 0 || undefined}
        value={field.state.value}
        disabled={props.disabled}
        onBlur={field.handleBlur}
        onChange={field.handleChange}
      />
    </FieldShell>
  );
}

export function NumberField(props: {
  label: string;
  required?: boolean;
  placeholder?: string;
  description?: string;
  disabled?: boolean;
  step?: string;
  /**
   * 清空时写 `null` 而不是 `NaN`——用于「留空即不限制」这类可空字段：值要原样提交给后端，
   * 不能被 `z.number()` 判失败态吞掉。
   */
  nullable?: boolean;
}) {
  const field = useFieldContext<number | null>();
  const value = field.state.value;
  const isEmpty = value === null || Number.isNaN(value);
  return (
    <FieldShell
      label={props.label}
      required={props.required}
      description={props.description}
      display={isEmpty ? null : <span className="tabular-nums">{String(value)}</span>}
    >
      <Input
        id={field.name}
        name={field.name}
        type="number"
        step={props.step}
        placeholder={props.placeholder}
        aria-required={props.required === true || undefined}
        aria-invalid={field.state.meta.errors.length > 0 || undefined}
        value={isEmpty ? "" : String(value)}
        disabled={props.disabled}
        onBlur={field.handleBlur}
        onChange={(event) => {
          // 空串裸转 Number 是 0,会把「清空了」写成「改成 0」;非 nullable 映射 NaN 让 z.number() 判失败,
          // nullable 映射 null 原样提交给后端的可空字段。
          const raw = event.target.value;
          if (raw.trim() === "") {
            field.handleChange(props.nullable ? null : Number.NaN);
            return;
          }
          field.handleChange(Number(raw));
        }}
      />
    </FieldShell>
  );
}

export function SwitchField(props: {
  label: string;
  required?: boolean;
  description?: string;
  disabled?: boolean;
}) {
  const L = useLocalization();
  const field = useFieldContext<boolean>();
  return (
    <FieldShell
      label={props.label}
      required={props.required}
      description={props.description}
      orientation="horizontal"
      display={L(field.state.value ? "Form:Yes" : "Form:No")}
    >
      <Switch
        id={field.name}
        aria-required={props.required === true || undefined}
        aria-invalid={field.state.meta.errors.length > 0 || undefined}
        checked={field.state.value}
        disabled={props.disabled}
        onCheckedChange={(checked: boolean) => field.handleChange(checked)}
      />
    </FieldShell>
  );
}

export function SelectField(props: {
  label: string;
  options: { value: string; label: string }[];
  required?: boolean;
  description?: string;
  disabled?: boolean;
}) {
  const field = useFieldContext<string>();
  // Radix 把 value === "" 当作「未选」，即便选项里有 value=""：选中项的文字不会同步进触发器，
  // 只会回退渲染 SelectValue 的 placeholder。给空值选项传它自己的 label 当 placeholder。
  const emptyOptionLabel = props.options.find((option) => option.value === "")?.label;
  return (
    <FieldShell
      label={props.label}
      required={props.required}
      description={props.description}
      display={props.options.find((option) => option.value === field.state.value)?.label ?? null}
    >
      <Select
        value={field.state.value}
        onValueChange={(value) => field.handleChange(value)}
        disabled={props.disabled}
      >
        <SelectTrigger
          id={field.name}
          className="w-full"
          aria-invalid={field.state.meta.errors.length > 0 || undefined}
        >
          <SelectValue placeholder={emptyOptionLabel} />
        </SelectTrigger>
        <SelectContent>
          {props.options.map((option) => (
            <SelectItem key={option.value} value={option.value}>
              {option.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </FieldShell>
  );
}

export function DateField(props: {
  label: string;
  required?: boolean;
  description?: string;
  disabled?: boolean;
  placeholder?: string;
  /** 透传给日期选择器，覆盖默认可选范围（见 DatePickerProps.startMonth）。 */
  startMonth?: Date;
  endMonth?: Date;
}) {
  const field = useFieldContext<string>();
  return (
    <FieldShell
      label={props.label}
      required={props.required}
      description={props.description}
      display={field.state.value ? <span className="tabular-nums">{field.state.value}</span> : null}
    >
      <Suspense fallback={<Skeleton className="h-9 w-full" />}>
        <DatePicker
          id={field.name}
          value={parseIso(field.state.value, ISO_DATE)}
          startMonth={props.startMonth}
          endMonth={props.endMonth}
          disabled={props.disabled}
          placeholder={props.placeholder}
          aria-required={props.required === true || undefined}
          aria-invalid={field.state.meta.errors.length > 0 || undefined}
          onChange={(date) => field.handleChange(formatIso(date, ISO_DATE))}
        />
      </Suspense>
    </FieldShell>
  );
}

export function DateTimeField(props: {
  label: string;
  description?: string;
  required?: boolean;
  disabled?: boolean;
  placeholder?: string;
  /** 透传给日期选择器，覆盖默认可选范围（见 DatePickerProps.startMonth）。 */
  startMonth?: Date;
  endMonth?: Date;
}) {
  const field = useFieldContext<string>();
  return (
    <FieldShell
      label={props.label}
      required={props.required}
      description={props.description}
      display={field.state.value ? <span className="tabular-nums">{field.state.value}</span> : null}
    >
      <Suspense fallback={<Skeleton className="h-9 w-full" />}>
        <DateTimePicker
          id={field.name}
          value={parseIso(field.state.value, ISO_DATE_TIME)}
          startMonth={props.startMonth}
          endMonth={props.endMonth}
          disabled={props.disabled}
          placeholder={props.placeholder}
          aria-required={props.required === true || undefined}
          aria-invalid={field.state.meta.errors.length > 0 || undefined}
          onChange={(date) => field.handleChange(formatIso(date, ISO_DATE_TIME))}
        />
      </Suspense>
    </FieldShell>
  );
}

export function DateRangeField(props: {
  label: string;
  description?: string;
  required?: boolean;
  disabled?: boolean;
  /** 透传给日期选择器，覆盖默认可选范围（见 DatePickerProps.startMonth）。 */
  startMonth?: Date;
  endMonth?: Date;
}) {
  const field = useFieldContext<{ from: string; to: string }>();
  return (
    <FieldShell
      label={props.label}
      required={props.required}
      description={props.description}
      display={
        field.state.value.from || field.state.value.to ? (
          <span className="tabular-nums">
            {field.state.value.from} – {field.state.value.to}
          </span>
        ) : null
      }
    >
      <Suspense fallback={<Skeleton className="h-9 w-full" />}>
        <DateRangePicker
          id={field.name}
          value={{
            from: parseIso(field.state.value.from, ISO_DATE),
            to: parseIso(field.state.value.to, ISO_DATE),
          }}
          startMonth={props.startMonth}
          endMonth={props.endMonth}
          disabled={props.disabled}
          aria-required={props.required === true || undefined}
          aria-invalid={field.state.meta.errors.length > 0 || undefined}
          onChange={(range) =>
            field.handleChange({
              from: formatIso(range?.from, ISO_DATE),
              to: formatIso(range?.to, ISO_DATE),
            })
          }
        />
      </Suspense>
    </FieldShell>
  );
}

export function ComboboxField(props: {
  label: string;
  description?: string;
  options?: ComboboxOption[];
  loadOptions?: (search: string) => Promise<ComboboxOption[]>;
  placeholder?: string;
  required?: boolean;
  disabled?: boolean;
}) {
  const field = useFieldContext<string>();
  return (
    <FieldShell
      label={props.label}
      required={props.required}
      description={props.description}
      display={
        props.options?.find((option) => option.value === field.state.value)?.label ??
        field.state.value
      }
    >
      <Combobox
        value={field.state.value || undefined}
        onChange={(value) => field.handleChange(value ?? "")}
        options={props.options ?? []}
        loadOptions={props.loadOptions}
        placeholder={props.placeholder}
        disabled={props.disabled}
      />
    </FieldShell>
  );
}

export function MultiComboboxField(props: {
  label: string;
  description?: string;
  options?: ComboboxOption[];
  /** 远程搜索：候选过多时用它替代整份 options，内部已带防抖。 */
  loadOptions?: (search: string) => Promise<ComboboxOption[]>;
  required?: boolean;
  placeholder?: string;
  /** 缺省 true。为 false 时只展示已选项（如当前用户无权修改）。 */
  editable?: boolean;
}) {
  const field = useFieldContext<string[]>();
  const editable = props.editable ?? true;
  // 有的字段值本身就是可读文案（如角色名），有的是 id（如成员）；后者靠调用方传入的 options
  // 换成 label，找不到就原样显示，不丢值。
  const labelOf = (value: string) =>
    props.options?.find((option) => option.value === value)?.label ?? value;
  const badges = field.state.value.map((value) => (
    <Badge key={value} variant="secondary">
      {labelOf(value)}
    </Badge>
  ));
  return (
    <FieldShell
      label={props.label}
      required={props.required}
      description={props.description}
      display={
        field.state.value.length === 0 ? null : (
          <div className="flex flex-wrap justify-end gap-1">{badges}</div>
        )
      }
    >
      {editable ? (
        <Suspense fallback={<Skeleton className="h-9 w-full" />}>
          <MultiCombobox
            id={field.name}
            aria-required={props.required === true || undefined}
            aria-invalid={field.state.meta.errors.length > 0 || undefined}
            values={field.state.value}
            onChange={(values) => field.handleChange(values)}
            options={props.options}
            loadOptions={props.loadOptions}
            placeholder={props.placeholder}
          />
        </Suspense>
      ) : (
        <div className="flex flex-wrap gap-1">
          {field.state.value.length === 0 ? (
            <span className="text-sm text-muted-foreground">—</span>
          ) : (
            badges
          )}
        </div>
      )}
    </FieldShell>
  );
}

/** onSubmitAsync 返回的 form 键落 state.errorMap.onSubmit;\n 拆多条渲染。 */
function FormErrors() {
  const form = useFormContext();
  return (
    <form.Subscribe selector={(state) => state.errorMap.onSubmit}>
      {(onSubmit) => {
        const message = typeof onSubmit === "string" ? onSubmit : undefined;
        return <FormErrorSummary errors={message ? message.split("\n") : []} />;
      }}
    </form.Subscribe>
  );
}

const { useAppForm: useAppFormBase, withForm } = createFormHook({
  fieldContext,
  formContext,
  fieldComponents: {
    TextField,
    NumberField,
    TextareaField,
    TimeField,
    SwitchField,
    SelectField,
    DateField,
    DateTimeField,
    DateRangeField,
    ComboboxField,
    MultiComboboxField,
  },
  formComponents: { FormErrors },
});

/** 提交结束后把焦点移到第一个仍有错误的字段;取不到 DOM 元素(如自定义组件未转发 id)则顺延到
 * 下一个可聚焦的错误字段。字段输入的 id 约定为 field.name(内置字段组件已遵守)。「第一个」按
 * fieldMeta 的字段注册序(≈挂载序/tab 序);条件渲染或重排字段的极端场景下未必是视觉最上者。 */
function focusFirstInvalidField(form: {
  state: { fieldMeta: Record<string, { errors?: unknown[] } | undefined> };
}): void {
  for (const [name, meta] of Object.entries(form.state.fieldMeta)) {
    if (!meta?.errors?.length) continue;
    const el = document.getElementById(name);
    if (el) {
      el.focus();
      return;
    }
  }
}

const patchedForms = new WeakSet<object>();

/**
 * 包装 useAppFormBase:提交前注入服务端错误清理(见 clearServerSubmitErrors),提交结束后聚焦
 * 首错字段(见 focusFirstInvalidField)。WeakSet 守卫而不是 useState/useRef，后者初始化器在
 * StrictMode 下双调用,保证不了只 patch 一次。
 */
export const useAppForm: typeof useAppFormBase = (opts) => {
  const form = useAppFormBase(opts);
  if (!patchedForms.has(form)) {
    patchedForms.add(form);
    const original = form.handleSubmit;
    form.handleSubmit = ((submitMeta?: unknown) => {
      clearServerSubmitErrors(form as unknown as ServerErrorForm);
      const result = submitMeta === undefined ? original() : original(submitMeta as never);
      return result.then(() => {
        focusFirstInvalidField(form as unknown as Parameters<typeof focusFirstInvalidField>[0]);
      });
    }) as typeof form.handleSubmit;
  }
  return form;
};

