export type SheetFormMode = "create" | "edit" | "view";

/**
 * 抽屉宽度档位。SheetForm 与手写的 `SheetContent` 共用这一份，页面里不直接写 `max-w`：
 * 宽度一旦散落在各页，换一次档位就要逐页找。
 *
 * `sm` 是配置类表单的常规宽度；`md` 给字段略多的录入；`lg` 给需要一张小表或明细列表的抽屉；
 * `xl` 留给要并排看表单与预览的页。
 */
export type SheetFormSize = "sm" | "md" | "lg" | "xl";

export const SHEET_SIZE_CLASS: Record<SheetFormSize, string> = {
  sm: "sm:max-w-md",
  md: "sm:max-w-lg",
  lg: "sm:max-w-2xl",
  xl: "sm:max-w-5xl",
};

export interface SheetFormProps {
  mode: SheetFormMode;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  /** 记录标识或状态，例如「刘慈欣 · 2008-01-01」。只放能帮人确认「我在改哪一条」的信息——
   *  写「保存后可继续编辑」这类通用说明不如不写，它占一行而读者只看一次。 */
  subtitle?: string;
  onSubmit?: () => void;
  canEdit?: boolean;
  onEdit?: () => void;
  pending?: boolean;
  /** 表单是否有未保存的改动。为真时，任何关闭动作都先过一道确认。 */
  dirty?: boolean;
  /** 抽屉宽度，默认 `sm`。见 `SheetFormSize`。 */
  size?: SheetFormSize;
  children: ReactNode;
}

/** 三态侧滑表单容器（对标 DrawerForm）。 */
export function SheetForm(props: SheetFormProps) {
  const L = useLocalization();
  const editable = props.mode !== "view";
  const [confirming, setConfirming] = useState(false);

  // 所有关闭路径都收敛到这里：Esc、右上角 ×、点遮罩、取消按钮。分散判断迟早漏掉一条，
  // 而「哪一条漏了」只有用户丢了数据才会发现。
  const requestClose = () => {
    if (props.dirty === true) {
      setConfirming(true);
      return;
    }
    props.onOpenChange(false);
  };

  return (
    <Sheet
      open={props.open}
      onOpenChange={(next) => (next ? props.onOpenChange(true) : requestClose())}
    >
      <SheetContent
        className={cn("flex w-full flex-col gap-0 p-0", SHEET_SIZE_CLASS[props.size ?? "sm"])}
        // Esc 自己兜一层，不依赖 Radix 的默认路径：焦点落在文本框里时浏览器会先消费掉这个键
        // （事件到达 document 时已 defaultPrevented），而表单一打开就自动聚焦第一个字段——
        // 于是模态最标准的退出键在实际使用中从来没生效过。
        onKeyDown={(event) => {
          if (event.key !== "Escape") return;
          event.stopPropagation();
          requestClose();
        }}
      >
        <SheetHeader className="gap-0 px-5 pt-5 pb-4 pr-12">
          <div className="flex items-start justify-between gap-2">
            <SheetTitle className="truncate">{props.title}</SheetTitle>
            {!editable && props.canEdit === true && (
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={props.onEdit}
                className="shrink-0"
              >
                <Pencil />
                {L("Form:Edit")}
              </Button>
            )}
          </div>
          {props.subtitle !== undefined && (
            <SheetDescription className="mt-1">{props.subtitle}</SheetDescription>
          )}
        </SheetHeader>
        {/* form 自身不滚：滚动下移一层，否则底部操作栏会跟着字段一起滚出屏幕。 */}
        <form
          className="flex flex-1 flex-col overflow-hidden"
          onSubmit={(event) => {
            event.preventDefault();
            props.onSubmit?.();
          }}
        >
          <div className="flex flex-1 flex-col gap-5 overflow-y-auto px-5 pb-5">
            {editable ? (
              // 录入表单里多数字段必填，所以标出选填的那一两个；查询表单反之，不开这个开关。
              <OptionalMarks>{props.children}</OptionalMarks>
            ) : (
              // 查看态借整页表单的容器语汇：一行一个字段、发丝线分隔、值右对齐排成一条竖线。
              // 一条记录于是读起来像「把一行表格竖过来」，而不是一排灰掉的输入框。
              <dl className="divide-y rounded-lg border bg-card">
                <ReadOnlyFields>{props.children}</ReadOnlyFields>
              </dl>
            )}
          </div>
          {editable && (
            // 单行右对齐、primary 最右，与整页表单同一套语法；取消用 ghost——它是退路，
            // 不是与保存并列的选项，不该也带一圈边框去争视觉重量。
            <div className="flex items-center justify-end gap-2 border-t px-5 py-3">
              <Button type="button" variant="ghost" onClick={requestClose}>
                {L("Form:Cancel")}
              </Button>
              <SubmitButton pending={props.pending} />
            </div>
          )}
        </form>
      </SheetContent>
      <AlertDialog open={confirming} onOpenChange={setConfirming}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{L("Form:DiscardTitle")}</AlertDialogTitle>
            <AlertDialogDescription>{L("Form:DiscardBody")}</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>{L("Form:KeepEditing")}</AlertDialogCancel>
            {/* 丢弃已填内容是不可逆的，而红色在这套系统里正是留给不可逆动作的。 */}
            <AlertDialogAction
              variant="destructive"
              onClick={() => {
                setConfirming(false);
                props.onOpenChange(false);
              }}
            >
              {L("Form:Discard")}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </Sheet>
  );
}

import type { ReactNode } from "react";
import { cn } from "@/lib/utils";

/**
 * 放进 `<div className="divide-y rounded-lg border bg-card">` 容器里连排，分区线由容器 divide-y 画。
 *
 * 落在 `SheetForm` 查看态的 `<dl>` 里时自动收成记录布局：去掉两栏网格与 p-6 内边距，标题变成
 * 一行小节头，字段行之间改由发丝线分隔——否则每个分区会顶着自己的留白挤在键值卡里，行的
 * 左右边距也与顶层 `FieldRow` 对不齐。
 */
export function FormSection(props: {
  title: string;
  description?: string;
  children: ReactNode;
  className?: string;
}) {
  return (
    <div
      className={cn(
        "grid gap-4 p-6 md:grid-cols-[220px_1fr] md:gap-8",
        "in-[dl]:block in-[dl]:p-0",
        props.className,
      )}
    >
      <div className="in-[dl]:px-3 in-[dl]:pt-3 in-[dl]:pb-1">
        <h3 className="text-sm font-semibold">{props.title}</h3>
        {props.description !== undefined && (
          <p className="mt-1.5 text-xs leading-relaxed text-muted-foreground">
            {props.description}
          </p>
        )}
      </div>
      <div className="min-w-0 space-y-4 in-[dl]:divide-y in-[dl]:space-y-0">{props.children}</div>
    </div>
  );
}

import type { ReactNode } from "react";
import { cn } from "@/lib/utils";

/**
 * 表单分区卡片：分区标题 + 卡片容器，宽抽屉（`size="lg"`/`"xl"`）里靠它把长表单切成几段。
 *
 * 与 `FormSection` 的分工：`FormSection` 是整页表单的「左标题 / 右字段」分区，靠外层
 * `divide-y` 容器连排；`FormCard` 是抽屉里自带外框的一段，彼此之间留空隙。标题与
 * `FormSection` 同规格（`text-sm font-semibold`）。
 *
 * 落在 `SheetForm` 查看态的 `<dl>` 里时与 `FormSection` 一样收成记录布局：去掉自己的外框与
 * 内边距，标题变成一行小节头，字段行之间改由发丝线分隔。整条记录于是只有外层那一张卡——
 * 卡片外的普通字段与卡片里的字段落在同一条竖线上，不会出现卡片套卡片或卡片旁的裸行。
 */
export function FormCard(props: {
  title: string;
  description?: string;
  children: ReactNode;
  className?: string;
}) {
  return (
    // div 而非 section：查看态的 SheetForm 把内容放进 <dl>，<dl> 里只允许 div 包裹 dt/dd
    <div
      data-form-card=""
      className={cn(
        "space-y-4 rounded-lg border bg-card p-4",
        "in-[dl]:space-y-0 in-[dl]:rounded-none in-[dl]:border-0 in-[dl]:bg-transparent in-[dl]:p-0",
        props.className,
      )}
    >
      <div className="space-y-1 in-[dl]:px-3 in-[dl]:pt-3 in-[dl]:pb-1">
        <h3 className="text-sm font-semibold">{props.title}</h3>
        {props.description !== undefined && (
          <p className="text-xs text-muted-foreground">{props.description}</p>
        )}
      </div>
      <div className="space-y-4 in-[dl]:space-y-0 in-[dl]:divide-y">{props.children}</div>
    </div>
  );
}

import type { ReactNode } from "react";
import { useReadOnly } from "@/components/form/form-hook";

/**
 * 页面为录入态写的排版层（多列栅格、行内 flex、纵向间距），查看态下退成 Fragment。
 *
 * 查看态每个字段已经是一行「键 / 值」。包裹层留着会有三个后果：行被并排、值不再排成一条竖线；
 * 发丝线落在包裹层上而不是每一行上；包裹层自己的内边距与行的 `px-3` 叠加，行和行对不齐。
 * 退成 Fragment 让行重新成为键值卡的直系子节点，这三件事一起消失。
 */
export function FieldLayout(props: { className: string; children: ReactNode }) {
  const readOnly = useReadOnly();
  if (readOnly) return <>{props.children}</>;
  return <div className={props.className}>{props.children}</div>;
}

/**
 * 填写指引，查看态不渲染。
 *
 * 它说的是「该怎么填」，读记录的人用不上；而且它不是 `FieldRow`，留在查看态的键值卡里会直接
 * 贴到卡片边框上。派生值（算出来的窗口、关联记录摘要）不属于这里，用 `FieldRow` 排进键值列。
 */
export function FieldHint(props: { children: ReactNode }) {
  const readOnly = useReadOnly();
  if (readOnly) return null;
  return <p className="text-sm text-muted-foreground">{props.children}</p>;
}

import { useLocalization } from "@jcoder-stack/abp-react/react";
import { cn } from "@/lib/utils";

/**
 * 选填字段 label 后的「选填」标记。
 *
 * 标的是**少数派**：后台表单里多数字段必填，逐个挂红星等于让一张还没被碰过的表单布满
 * 错误信号，而红色在本系统里只表示出错与危险，这么用会把它的分量花掉。改为只标选填，
 * 一张表上通常只剩一两个标记。
 *
 * 与 RequiredMark 一样只是视觉提示（`aria-hidden`）：必填语义由控件自身的
 * `required`/`aria-required` 承载，不让读屏把标记和属性念两遍。
 */
export function OptionalMark({ className }: { className?: string }) {
  const L = useLocalization();
  return (
    <span
      aria-hidden
      className={cn("ml-1 font-normal text-muted-foreground select-none", className)}
    >
      {L("Form:Optional")}
    </span>
  );
}

export type FieldErrors = { field?: string; message: string }[];

/** `onSubmitAsync` 校验器的返回形状:`form` 落表单级(state.errorMap.onSubmit)、`fields` 落各字段(field.state.meta.errors)。 */
export interface ServerErrorMap {
  form?: string;
  fields: Record<string, string>;
}

/** 通用 FieldErrors → onSubmitAsync 返回形状;空输入返回 null(表示校验通过)。 */
export function toErrorMap(errors: FieldErrors): ServerErrorMap | null {
  if (errors.length === 0) return null;
  const fields: Record<string, string> = {};
  const formLevel: string[] = [];
  for (const error of errors) {
    if (error.field) {
      fields[error.field] = fields[error.field]
        ? `${fields[error.field]}\n${error.message}`
        : error.message;
    } else {
      formLevel.push(error.message);
    }
  }
  const map: ServerErrorMap = { fields };
  if (formLevel.length > 0) map.form = formLevel.join("\n");
  return map;
}

/**
 * 把「提交 + 服务端错误落字段」封装成一个 onSubmitAsync 校验器。`mapError` 是
 * 后端协议注入点(不认识任何具体后端;ABP 版实现见 components/abp/crud/abp-form-errors)。
 * mapError 映射不出错误(非校验类失败)时回退 Error.message 作表单级错误,绝不静默吞掉。
 */
export function serverSubmitValidator<TValue>(
  submit: (value: TValue) => Promise<void>,
  mapError: (error: unknown) => FieldErrors,
) {
  return async ({ value }: { value: TValue }): Promise<ServerErrorMap | null> => {
    try {
      await submit(value);
      return null;
    } catch (error) {
      const mapped = toErrorMap(mapError(error));
      if (mapped) return mapped;
      return {
        form: error instanceof Error ? error.message : String(error),
        fields: {},
      };
    }
  };
}

import { useLocalization } from "@jcoder-stack/abp-react/react";
import { Loader2 } from "lucide-react";
import type { ReactNode } from "react";
import { Button } from "@/components/ui/button";

export function SubmitButton({ pending, children }: { pending?: boolean; children?: ReactNode }) {
  const L = useLocalization();
  return (
    <Button type="submit" disabled={pending}>
      {pending === true && <Loader2 className="animate-spin" />}
      {children ?? L("Form:Save")}
    </Button>
  );
}

import { useLocalization } from "@jcoder-stack/abp-react/react";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";

export function FormErrorSummary({ errors }: { errors: string[] }) {
  const L = useLocalization();
  if (errors.length === 0) return null;
  return (
    <Alert variant="destructive">
      <AlertTitle>{L("Form:SubmitFailed")}</AlertTitle>
      <AlertDescription>
        {errors.map((message) => (
          <p key={message}>{message}</p>
        ))}
      </AlertDescription>
    </Alert>
  );
}
